package com.guocheng.mediapocket;
import android.widget.*;import org.json.*;import java.util.concurrent.*;
/** 首页上的 Emby：继续观看用 Resume，每个媒体库一行最新。走现有的大图和横滑海报，不改海报布局。 */
final class EmbyHome {
 static final ExecutorService IO=Executors.newFixedThreadPool(2,r->{Thread t=new Thread(r,"emby-home");t.setDaemon(true);return t;});
 private EmbyHome(){}
 static void show(ScrapedMainActivity a){final int ticket=a.epoch;JSONObject server=selected(a);LinearLayout target=section(a);if(server==null){target.addView(a.heading("Emby"));target.addView(a.text("还没有 Emby 服务器，请到设置里添加",13,a.muted()));target.addView(a.button("添加 Emby 服务器",()->EmbyLibraryActivity.manage(a)));return;}
  target.addView(a.text("正在读取 "+EmbyStore.label(server)+" …",12,a.muted()));
  IO.execute(()->{try{JSONArray resume=rows(EmbyClient.resume(a,server));JSONArray views=rows(EmbyClient.views(a,server));java.util.ArrayList<JSONObject> libs=libraries(views);java.util.ArrayList<JSONArray> latest=new java.util.ArrayList<>();JSONArray heroes=new JSONArray();
   for(JSONObject lib:libs){JSONArray items=rows(EmbyClient.latest(a,server,lib.optString("Id")));latest.add(items);for(int i=0;i<items.length()&&heroes.length()<5;i++){JSONObject m=card(a,server,items.optJSONObject(i),false);if(m!=null&&!EmbyApi.backdropTag(items.optJSONObject(i)).isEmpty())heroes.put(m);}}
   if(heroes.length()==0)for(int i=0;i<resume.length()&&heroes.length()<5;i++){JSONObject m=card(a,server,resume.optJSONObject(i),true);if(m!=null)heroes.put(m);}
   final JSONArray heroItems=heroes;a.runOnUiThread(()->{if(ticket!=a.epoch||a.isFinishing())return;target.removeAllViews();if(heroItems.length()>0){a.heroPriority=4;a.setHeroes(heroItems,heroItems.optJSONObject(0).optString("type","movie"));}
    JSONArray cont=new JSONArray();for(int i=0;i<resume.length();i++){JSONObject m=card(a,server,resume.optJSONObject(i),true);if(m!=null)cont.put(m);}if(a.homeChrome==null)a.homeChrome=new HomeChrome(a);if(cont.length()>0)a.homeChrome.continueWatching(target,cont,"继续观看");
    if(libs.isEmpty())target.addView(a.text("这个账号还没有媒体库",13,a.muted()));
    for(int i=0;i<libs.size();i++){JSONObject lib=libs.get(i);JSONArray items=latest.get(i);TextView heading=a.heading("最新 · "+lib.optString("Name","媒体库")+" ›");String id=lib.optString("Id");heading.setOnClickListener(v->EmbyLibraryActivity.openLibrary(a,server.optString("id"),id));target.addView(heading);LinearLayout shelf=new LinearLayout(a);shelf.setOrientation(1);target.addView(shelf);JSONArray metas=new JSONArray();for(int n=0;n<items.length();n++){JSONObject m=card(a,server,items.optJSONObject(n),false);if(m!=null)metas.put(m);}if(metas.length()==0)shelf.addView(a.text("此媒体库暂时没有新条目",12,a.muted()));else a.shelf(shelf,metas,"movie",false);}});
  }catch(Exception e){a.runOnUiThread(()->{if(ticket!=a.epoch||a.isFinishing())return;target.removeAllViews();target.addView(a.heading("Emby"));target.addView(a.text(EmbyApi.explain(e),13,a.muted()));target.addView(a.button("重试",()->a.home()));});}});}
 static void supplement(ScrapedMainActivity a){if("emby".equals(a.homeProvider))return;JSONArray servers=EmbyStore.list(a);if(servers.length()==0)return;final int ticket=a.epoch;LinearLayout target=section(a);IO.execute(()->{try{JSONArray blocks=new JSONArray();
   for(int s=0;s<servers.length();s++){JSONObject server=servers.optJSONObject(s);if(server==null)continue;JSONArray resume=rows(EmbyClient.resume(a,server));JSONArray cont=new JSONArray();for(int i=0;i<resume.length();i++){JSONObject m=card(a,server,resume.optJSONObject(i),true);if(m!=null)cont.put(m);}if(cont.length()>0)blocks.put(new JSONObject().put("title","继续观看 · "+server.optString("name","Emby")).put("items",cont).put("continue",true));
    JSONArray views=rows(EmbyClient.views(a,server));int shown=0;for(JSONObject lib:libraries(views)){if(shown>=6)break;JSONArray items=rows(EmbyClient.latest(a,server,lib.optString("Id")));JSONArray metas=new JSONArray();for(int n=0;n<items.length();n++){JSONObject m=card(a,server,items.optJSONObject(n),false);if(m!=null)metas.put(m);}if(metas.length()>0){blocks.put(new JSONObject().put("title","最新 · "+lib.optString("Name","媒体库")).put("items",metas));shown++;}}}
   a.runOnUiThread(()->{if(ticket!=a.epoch||a.isFinishing()||!a.homeCanvas)return;target.removeAllViews();if(a.homeChrome==null)a.homeChrome=new HomeChrome(a);for(int i=0;i<blocks.length();i++){JSONObject b=blocks.optJSONObject(i);if(b==null)continue;if(b.optBoolean("continue"))a.homeChrome.continueWatching(target,b.optJSONArray("items"),b.optString("title"));else{target.addView(a.heading(b.optString("title")+" ›"));LinearLayout shelf=new LinearLayout(a);shelf.setOrientation(1);target.addView(shelf);a.shelf(shelf,b.optJSONArray("items"),"movie",false);}}});
  }catch(Exception ignored){}});}
 static JSONObject selected(ScrapedMainActivity a){String id=a.prefs.getString("home.source.v1","");JSONObject s=EmbyStore.get(a,id);if(s!=null)return s;JSONArray all=EmbyStore.list(a);return all.length()==0?null:all.optJSONObject(0);}
 static LinearLayout section(ScrapedMainActivity a){LinearLayout t=new LinearLayout(a);t.setOrientation(1);a.body.addView(t);return t;}
 static JSONArray rows(JSONObject response){if(response==null)return new JSONArray();JSONArray items=response.optJSONArray("Items");return items==null?new JSONArray():items;}
 static java.util.ArrayList<JSONObject> libraries(JSONArray views){java.util.ArrayList<JSONObject> out=new java.util.ArrayList<>();for(int i=0;i<views.length();i++){JSONObject v=views.optJSONObject(i);if(v!=null&&EmbyApi.library(v))out.add(v);}return out;}
 static JSONObject card(ScrapedMainActivity a,JSONObject server,JSONObject item,boolean resume){try{if(item==null||item.optString("Id").isEmpty())return null;JSONObject m=EmbyApi.meta(server,item);if(resume)m.put("emby.directPlay",true);long ms=m.optLong("emby.resumeMs");if(ms>0){String id=m.optString("id");int dur=(int)Math.min(Integer.MAX_VALUE,EmbyApi.ticksToMs(item.optLong("RunTimeTicks")));if(a.prefs.getInt("pos:"+id,0)<=0)a.prefs.edit().putInt("pos:"+id,(int)Math.min(Integer.MAX_VALUE,ms)).putInt("dur:"+id,dur).apply();}return m;}catch(Exception e){return null;}}
}
